  void addDoc(Doc* doc);
  void removeDoc(Doc* doc);
  void getActiveSiteForDoc(Doc* doc, Site* site);
  void setActiveLayerInDoc(Doc* doc, doc::Layer* layer);
  void setActiveFrameInDoc(Doc* doc, doc::frame_t frame);
